// FUNCTION: BFME2 0x00714BD0 size=36 name=?eval_overlap_mask@CollisionMath@@CA?AW4OverlapType@1@H@Z evidence=N:ledger tier=B hypothesis:Z
CollisionMath::OverlapType CollisionMath::eval_overlap_mask(int mask)
{
	if (mask == ON) {
		return ON;
	}
	if ((mask & ~(POS | ON)) == 0) {
		return POS;
	}
	if ((mask & ~(NEG | ON)) != 0) {
		return BOTH;
	}
	return NEG;
}

// FUNCTION: BFME2 0x00714C00 size=181 name=?Rotate_Vector@Matrix3@@SAXABV1@ABVVector3@@PAV2@@Z evidence=N:ledger tier=B hypothesis:Z
void Matrix3::Rotate_Vector(const Matrix3 &A, const Vector3 &in, Vector3 *out)
{
	Vector3 copy;
	const Vector3 *v;
	if (out == &in) {
		copy = in;
		v = &copy;
	} else {
		v = &in;
	}
	out->X = A[0][0] * (*v)[0] + A[0][1] * (*v)[1] + A[0][2] * (*v)[2];
	out->Y = A[1][0] * (*v)[0] + A[1][1] * (*v)[1] + A[1][2] * (*v)[2];
	out->Z = A[2][0] * (*v)[0] + A[2][1] * (*v)[1] + A[2][2] * (*v)[2];
}

// FUNCTION: BFME2 0x00714CC0 size=181 name=?Transpose_Rotate_Vector@Matrix3@@SAXABV1@ABVVector3@@PAV2@@Z evidence=N:ledger tier=B hypothesis:Z
void Matrix3::Transpose_Rotate_Vector(const Matrix3 &A, const Vector3 &in, Vector3 *out)
{
	Vector3 copy;
	const Vector3 *v;
	if (out == &in) {
		copy = in;
		v = &copy;
	} else {
		v = &in;
	}
	out->X = A[0][0] * (*v)[0] + A[1][0] * (*v)[1] + A[2][0] * (*v)[2];
	out->Y = A[0][1] * (*v)[0] + A[1][1] * (*v)[1] + A[2][1] * (*v)[2];
	out->Z = A[0][2] * (*v)[0] + A[1][2] * (*v)[1] + A[2][2] * (*v)[2];
}

